package com.nivor.ai;import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;
@Entity @Table(name="ai_access_preferences",uniqueConstraints=@UniqueConstraint(name="uq_ai_access_user_category",columnNames={"user_id","category"}))public class AiAccessPreference extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private AiContextCategory category;@Column(nullable=false)private boolean enabled;protected AiAccessPreference(){}public User getUser(){return user;}public void setUser(User v){user=v;}public AiContextCategory getCategory(){return category;}public void setCategory(AiContextCategory v){category=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}}
